// Soft, friendly, no metallic / cinematic / tactical.
// Generated by Claude Design from spec, hand-converted to TS.

import { useState, type ReactNode } from 'react';
import { Avatar, Badge, Button, Card, Icon, Input } from '@/components/design/ui';

type Game = {
  id: string;
  code: string;
  name: string;
  short: string;
  grad: string;
};

type RoomKind = 'Official' | 'Personal';

type Room = {
  id: number;
  kind: RoomKind;
  title: string;
  host: string;
  region: string;
  ping: number;
  diff: string;
  mode: string;
  lives: number;
  seats: number;
  taken: number;
  grad: string;
};

type FriendStatus = 'online' | 'away' | 'dnd' | 'offline';

type Friend = {
  name: string;
  handle: string;
  status: FriendStatus;
  game: string;
};

type ChatLine = {
  who: string;
  handle: string;
  t: string;
  msg: string;
  mention?: string | false;
  share?: number;
};

