// ---------- Tiny pieces ----------
function GameTile({ g, active, onClick }: { g: Game; active: boolean; onClick: () => void }) {
  return (
    <div style={{ position: 'relative', display: 'flex', justifyContent: 'center' }}>
      <span
        style={{
          position: 'absolute',
          left: -10,
          top: '50%',
          transform: 'translateY(-50%)',
          width: 4,
          height: active ? 28 : 0,
          background: 'var(--fg-0)',
          borderRadius: 999,
          transition: 'height .2s ease',
        }}
      />
      <button
        onClick={onClick}
        title={`${g.code} · ${g.name}`}
        style={{
          width: 48,
          height: 48,
          borderRadius: active ? 14 : 24,
          background: g.grad,
          color: '#fff',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          fontFamily: 'var(--font-thp-display)',
          fontWeight: 800,
          fontSize: 13,
          letterSpacing: '0.02em',
          cursor: 'pointer',
          border: 'none',
          padding: 0,
          boxShadow: active ? '0 4px 14px rgba(0,0,0,0.18)' : 'var(--shadow-sm)',
          transition: 'border-radius .18s ease, transform .18s ease',
        }}
        onMouseEnter={(e) => {
          e.currentTarget.style.borderRadius = '14px';
        }}
        onMouseLeave={(e) => {
          e.currentTarget.style.borderRadius = active ? '14px' : '24px';
        }}
      >
        {g.code}
      </button>
    </div>
  );
}

function PlainTile({
  children,
  label,
  active,
  onClick,
  color,
}: {
  children: ReactNode;
  label: string;
  active?: boolean;
  onClick?: () => void;
  color?: string;
}) {
  return (
    <div style={{ position: 'relative', display: 'flex', justifyContent: 'center' }}>
      <span
        style={{
          position: 'absolute',
          left: -10,
          top: '50%',
          transform: 'translateY(-50%)',
          width: 4,
          height: active ? 28 : 0,
          background: 'var(--fg-0)',
          borderRadius: 999,
        }}
      />
      <button
        onClick={onClick}
        title={label}
        style={{
          width: 48,
          height: 48,
          borderRadius: active ? 14 : 24,
          background: 'var(--bg-2)',
          color: color || 'var(--fg-1)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          cursor: 'pointer',
          border: '1px solid var(--border)',
          padding: 0,
          transition: 'border-radius .18s ease, color .18s, background .18s',
        }}
        onMouseEnter={(e) => {
          e.currentTarget.style.borderRadius = '14px';
          e.currentTarget.style.color = 'var(--brand)';
        }}
        onMouseLeave={(e) => {
          e.currentTarget.style.borderRadius = active ? '14px' : '24px';
          e.currentTarget.style.color = color || 'var(--fg-1)';
        }}
      >
        {children}
      </button>
    </div>
  );
}

function Chip({
  active,
  locked,
  children,
  onClick,
  tooltip,
}: {
  active?: boolean;
  locked?: boolean;
  children: ReactNode;
  onClick?: () => void;
  tooltip?: string;
}) {
  return (
    <button
      onClick={onClick}
      title={tooltip}
      style={{
        height: 28,
        paddingInline: 11,
        gap: 6,
        display: 'inline-flex',
        alignItems: 'center',
        borderRadius: 999,
        fontSize: 12,
        fontWeight: 600,
        fontFamily: 'var(--font-thp-sans)',
        background: active ? 'var(--brand-soft)' : 'transparent',
        color: active ? 'var(--brand)' : locked ? 'var(--fg-3)' : 'var(--fg-1)',
        border: `1px solid ${active ? 'transparent' : 'var(--border-strong)'}`,
        cursor: locked ? 'help' : 'pointer',
        opacity: locked ? 0.7 : 1,
      }}
    >
      {locked ? <span style={{ display: 'inline-flex' }}>{Icon.lock}</span> : null}
      {children}
    </button>
  );
}

function VersionPill({
  active,
  dim,
  children,
}: {
  active?: boolean;
  dim?: boolean;
  children: ReactNode;
}) {
  return (
    <span
      style={{
        height: 24,
        paddingInline: 10,
        display: 'inline-flex',
        alignItems: 'center',
        borderRadius: 999,
        fontSize: 11.5,
        fontWeight: 700,
        letterSpacing: '0.02em',
        cursor: 'pointer',
        fontFamily: 'var(--font-thp-sans)',
        background: active ? 'var(--brand)' : 'var(--bg-2)',
        color: active ? '#fff' : dim ? 'var(--fg-3)' : 'var(--fg-1)',
        border: active ? 'none' : '1px solid var(--border)',
        opacity: dim ? 0.6 : 1,
      }}
    >
      {children}
    </span>
  );
}

function CardCover({ grad, kind }: { grad: string; kind: RoomKind }) {
  return (
    <div
      style={{
        position: 'relative',
        aspectRatio: '16 / 9',
        borderRadius: 'var(--r-md)',
        background: grad,
        overflow: 'hidden',
      }}
    >
      <div
        style={{
          position: 'absolute',
          inset: 0,
          background:
            'radial-gradient(60% 50% at 80% 20%, rgba(255,255,255,0.28) 0%, transparent 60%), radial-gradient(50% 50% at 15% 85%, rgba(255,255,255,0.16) 0%, transparent 60%)',
        }}
      />
      <span
        style={{
          position: 'absolute',
          top: 10,
          left: 10,
          height: 22,
          paddingInline: 9,
          display: 'inline-flex',
          alignItems: 'center',
          gap: 5,
          borderRadius: 999,
          background: 'rgba(0,0,0,0.28)',
          color: '#fff',
          backdropFilter: 'blur(8px)',
          WebkitBackdropFilter: 'blur(8px)',
          fontSize: 10.5,
          fontWeight: 700,
          letterSpacing: '0.02em',
        }}
      >
        <span
          style={{
            width: 5,
            height: 5,
            borderRadius: '50%',
            background: kind === 'Official' ? '#4ADE80' : '#F5B544',
          }}
        />
        {kind}
      </span>
    </div>
  );
}

function PlayerSeats({ taken, total }: { taken: number; total: number }) {
  const palette = [
    'var(--grad-violet)',
    'var(--grad-teal)',
    'var(--grad-amber)',
    'var(--grad-mint)',
  ];
  return (
    <div style={{ display: 'flex', gap: 6 }}>
      {Array.from({ length: total }).map((_, i) => {
        const filled = i < taken;
        return (
          <span key={i} style={{ position: 'relative' }}>
            <span
              style={{
                width: 26,
                height: 26,
                borderRadius: '50%',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                background: filled ? palette[i % palette.length] : 'var(--bg-2)',
                border: filled
                  ? '2px solid var(--bg-1)'
                  : '1.5px dashed var(--border-strong)',
                boxSizing: 'border-box',
                color: '#fff',
                fontSize: 10,
                fontWeight: 700,
              }}
            >
              {!filled && <span style={{ color: 'var(--fg-3)' }}>+</span>}
            </span>
            {filled && i === 0 ? (
              <span
                style={{
                  position: 'absolute',
                  top: -3,
                  right: -3,
                  width: 14,
                  height: 14,
                  borderRadius: '50%',
                  background: 'var(--warning)',
                  color: '#1A1B22',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  border: '1.5px solid var(--bg-1)',
                }}
              >
                {Icon.crown}
              </span>
            ) : null}
          </span>
        );
      })}
    </div>
  );
}

function RoomCard({ r, onJoin }: { r: Room; onJoin?: () => void }) {
  const full = r.taken >= r.seats;
  return (
    <Card padded={false} hover style={{ display: 'flex', flexDirection: 'column' }}>
      <div style={{ padding: 10 }}>
        <CardCover grad={r.grad} kind={r.kind} />
      </div>
      <div
        style={{
          padding: '4px 14px 14px 14px',
          display: 'flex',
          flexDirection: 'column',
          gap: 10,
        }}
      >
        <div>
          <div
            className="cjk"
            style={{
              fontSize: 16,
              fontWeight: 700,
              color: 'var(--fg-0)',
              letterSpacing: '-0.005em',
              lineHeight: 1.25,
            }}
          >
            {r.title}
          </div>
          <div
            style={{
              fontSize: 12,
              color: 'var(--fg-2)',
              marginTop: 4,
              display: 'flex',
              alignItems: 'center',
              gap: 6,
            }}
          >
            TH08 ·{' '}
            <span
              style={{
                color:
                  r.ping < 40
                    ? 'var(--success)'
                    : r.ping < 70
                      ? 'var(--warning)'
                      : 'var(--danger)',
              }}
            >
              {r.ping}ms
            </span>{' '}
            · {r.region}
          </div>
        </div>
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6 }}>
          <Badge tone="brand">{r.diff}</Badge>
          <Badge tone="neutral">{r.mode}</Badge>
          <Badge tone="neutral">{r.lives} lives</Badge>
        </div>
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            gap: 8,
          }}
        >
          <PlayerSeats taken={r.taken} total={r.seats} />
          <span className="cjk" style={{ fontSize: 11.5, color: 'var(--fg-2)' }}>
            <span style={{ color: 'var(--fg-1)', fontWeight: 600 }}>房主</span> {r.host}
          </span>
        </div>
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            gap: 10,
            paddingTop: 6,
            borderTop: '1px solid var(--border)',
            marginTop: 2,
          }}
        >
          <span style={{ fontSize: 12, color: 'var(--fg-1)', fontWeight: 600 }}>
            {r.taken}/{r.seats}{' '}
            <span style={{ color: 'var(--fg-2)', fontWeight: 500 }}>seats taken</span>
          </span>
          <Button variant={full ? 'secondary' : 'primary'} size="sm" onClick={onJoin}>
            {full ? 'Watch' : 'Join'}
          </Button>
        </div>
      </div>
    </Card>
  );
}

